let p = ctx.player;
if (!p) return;

let Component = Java.loadClass('net.minecraft.network.chat.Component');
let cost = Math.round(ctx['aeon_cost'] || 5);
let cooldownTicks = Math.round(ctx['aeon_cooldown'] || 200);

// 1. Level-Kosten prüfen
if (p.experienceLevel < cost) {
    global.Stones.playSound(p, 'minecraft:entity.villager.no', 'players', 1.0, 0.8);
    if (typeof p.sendSystemMessage === 'function') {
        p.sendSystemMessage(Component.literal('§c[Aeon Core] Du benötigst mindestens ' + cost + ' XP-Level!'));
    }
    return;
}

// 2. Schrein-Daten abfragen
let dimLoc = global.Stones.readNbt(p, 'ForgeCaps."stones:shrine_link".dim');
let posX = global.Stones.readNbt(p, 'ForgeCaps."stones:shrine_link".pos.X');
let posY = global.Stones.readNbt(p, 'ForgeCaps."stones:shrine_link".pos.Y');
let posZ = global.Stones.readNbt(p, 'ForgeCaps."stones:shrine_link".pos.Z');

if (dimLoc && dimLoc != 0 && dimLoc != '0') {
    let targetX = Number(posX) + 0.5;
    let targetY = Number(posY) + 1.0;
    let targetZ = Number(posZ) + 0.5;
    let targetSelector = p.username || (p.uuid ? p.uuid.toString() : p.stringUUID);

    p.giveExperienceLevels(-cost);
    global.Stones.setCooldown(p, 'milestone_aeoncore', cooldownTicks);

    p.server.runCommandSilent(`execute in ${dimLoc} run tp ${targetSelector} ${targetX} ${targetY} ${targetZ}`);

    global.Stones.playSound(p, 'minecraft:block.portal.travel', 'players', 0.8, 1.2);
    global.Stones.spawnParticles(p, 'minecraft:portal', p.position(), 35, 0.5, 0.5, 0.5, 0.1);
    return;
}

// Fallback: Kein Schrein gebunden
global.Stones.playSound(p, 'minecraft:entity.villager.no', 'players', 1.0, 0.8);
if (typeof p.sendSystemMessage === 'function') {
    p.sendSystemMessage(Component.literal('§c[Aeon Core] Kein Schrein verknüpft!'));
}
